/**
 * The cross-language contract.
 *
 * `test-vectors/` is generated by `contracts/ual/src/vectors.rs` using the exact canonical
 * form and hash functions the deployed contract runs. This file reproduces every one of those
 * strings and digests in TypeScript. If Rust and TypeScript ever disagree about what the
 * canonical bytes are, receipts stop being verifiable in the browser and this suite fails.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";

import {
  assertPolicyBytesCanonical,
  canonical,
  CanonicalError,
  genesisHash,
  parseCanonicalJson,
  sha256Hex,
} from "../src/canonical.js";
import { receiptHash, verifyChain, type Receipt } from "../src/receipts.js";

const VECTORS = join(import.meta.dirname, "..", "..", "..", "test-vectors");

function load<T>(name: string): T {
  return JSON.parse(readFileSync(join(VECTORS, name), "utf8")) as T;
}

describe("canonical.json", () => {
  const vec = load<{
    accept: { name: string; rawJson: string; canonical: string; sha256: string }[];
    reject: { name: string; rawJson: string; error: string; why: string }[];
  }>("canonical.json");

  it("has vectors to check", () => {
    expect(vec.accept.length).toBeGreaterThan(5);
    expect(vec.reject.length).toBeGreaterThan(3);
  });

  for (const c of vec.accept) {
    it(`accepts ${c.name} and matches the Rust bytes`, () => {
      expect(canonical(parseCanonicalJson(c.rawJson))).toBe(c.canonical);
      expect(sha256Hex(c.canonical)).toBe(c.sha256);
    });
  }

  for (const c of vec.reject) {
    it(`refuses ${c.name} with ${c.error} (${c.why})`, () => {
      let thrown: unknown;
      try {
        // parseCanonicalJson first: the float cases are only detectable in the raw bytes,
        // because JSON.parse turns 100.0 into the integer 100 and loses the evidence.
        canonical(parseCanonicalJson(c.rawJson));
      } catch (e) {
        thrown = e;
      }
      expect(thrown, "must throw").toBeInstanceOf(CanonicalError);
      expect((thrown as CanonicalError).code).toBe(c.error);
    });
  }

  it("plain JSON.parse is not enough for float syntax, which is why parseCanonicalJson exists", () => {
    // Documents the asymmetry rather than leaving it as folklore: after JSON.parse, the
    // canonicaliser cannot tell 100.0 from 100, so it accepts bytes the contract rejects.
    expect(canonical(JSON.parse('{"x":100.0}'))).toBe('{"x":100}');
    expect(() => parseCanonicalJson('{"x":100.0}')).toThrow(CanonicalError);
  });
});

describe("hashes.json", () => {
  const vec = load<{
    cases: { utf8: string; sha256: string }[];
    genesis: { contractId: string; deskId: string; genesisHash: string };
  }>("hashes.json");

  for (const c of vec.cases) {
    it(`sha256 of ${JSON.stringify(c.utf8).slice(0, 40)}`, () => {
      expect(sha256Hex(c.utf8)).toBe(c.sha256);
    });
  }

  it("derives the same genesis head as the contract", () => {
    expect(genesisHash(vec.genesis.contractId, vec.genesis.deskId)).toBe(
      vec.genesis.genesisHash,
    );
  });
});

describe("policies.json", () => {
  const vec = load<{
    valid: { policyJson: string; policyHash: string };
    invalid: { name: string; policyJson: string; error: string; why: string }[];
  }>("policies.json");

  it("the valid policy is already canonical, which is what commit_policy demands", () => {
    expect(canonical(parseCanonicalJson(vec.valid.policyJson))).toBe(vec.valid.policyJson);
    // The pre-check agrees, so a caller never spends a transaction to learn this.
    expect(() => assertPolicyBytesCanonical(vec.valid.policyJson)).not.toThrow();
  });

  it("policyHash is sha256 of the canonical bytes", () => {
    expect(sha256Hex(vec.valid.policyJson)).toBe(vec.valid.policyHash);
  });

  for (const c of vec.invalid.filter((x) => x.error === "E04_POLICY_NOT_CANONICAL")) {
    it(`detects ${c.name} locally before spending a transaction on it`, () => {
      // A local pre-check can catch exactly this class: the bytes differ from their own
      // canonical form. SPEC.md 8.1 wants the SDK to run the same checks as the contract.
      expect(() => assertPolicyBytesCanonical(c.policyJson)).toThrowError(
        /E04_POLICY_NOT_CANONICAL/,
      );
    });
  }
});

describe("evidence.json", () => {
  const vec = load<{
    fetcherPublicKey: string;
    items: {
      name: string;
      item: Record<string, unknown>;
      signingString: string;
      signingStringSha256: string;
      evidenceId: string;
    }[];
  }>("evidence.json");

  for (const c of vec.items) {
    it(`${c.name}: the signed bytes are canonical(item)`, () => {
      expect(canonical(c.item)).toBe(c.signingString);
      expect(sha256Hex(c.signingString)).toBe(c.signingStringSha256);
    });

    it(`${c.name}: evidenceId is the item's contentHash`, () => {
      // An item is addressed by what it said, not by who reported it. SPEC.md 2A.2 item 1.
      expect(c.evidenceId).toBe(c.item.contentHash);
    });

    it(`${c.name}: stance is not part of the signed payload`, () => {
      // The verifier assigns stance, not the fetcher, so it must stay outside the signature.
      expect(Object.keys(c.item)).not.toContain("stance");
    });
  }
});

describe("receipts.json", () => {
  const vec = load<{
    contractId: string;
    deskId: string;
    genesisHash: string;
    receipts: { receipt: Receipt; canonicalWithoutHash: string; hash: string }[];
  }>("receipts.json");

  it("has a run of receipts including a refusal", () => {
    expect(vec.receipts.length).toBeGreaterThan(4);
    const verdicts = vec.receipts.map((r) => r.receipt.verdict);
    expect(verdicts).toContain("APPROVED");
    expect(verdicts).toContain("REJECTED");
  });

  for (const { receipt, canonicalWithoutHash, hash } of vec.receipts) {
    it(`receipt ${receipt.seq} (${receipt.kind}) canonicalises to the same bytes`, () => {
      const body: Record<string, unknown> = { ...(receipt as unknown as Record<string, unknown>) };
      delete body.hash;
      expect(canonical(body)).toBe(canonicalWithoutHash);
    });

    it(`receipt ${receipt.seq} (${receipt.kind}) hash recomputes`, () => {
      expect(receiptHash(receipt)).toBe(hash);
      expect(receipt.hash).toBe(hash);
    });
  }

  it("every receipt carries the identical key set regardless of kind", () => {
    // The canonical shape must not depend on the kind, or a reader would need to know the
    // kind before it could verify the hash.
    const keySets = vec.receipts.map((r) => Object.keys(r.receipt).sort().join(","));
    expect(new Set(keySets).size).toBe(1);
  });

  it("verifies the chain end to end against the desk genesis", () => {
    const receipts = vec.receipts.map((r) => r.receipt);
    const result = verifyChain(receipts, genesisHash(vec.contractId, vec.deskId));
    expect(result.reason).toBeUndefined();
    expect(result.valid).toBe(true);
  });

  it("reports the exact seq when one byte is tampered with", () => {
    const receipts = vec.receipts.map((r) => ({ ...r.receipt }));
    const target = Math.min(3, receipts.length - 1);
    // Change the recorded equity on one receipt and nothing else.
    receipts[target] = { ...receipts[target], equityUsd: "99999999999" };
    const result = verifyChain(receipts, genesisHash(vec.contractId, vec.deskId));
    expect(result.valid).toBe(false);
    expect(result.brokenAt).toBe(receipts[target].seq);
  });

  it("rejects a run rebased onto a different genesis", () => {
    const receipts = vec.receipts.map((r) => r.receipt);
    const result = verifyChain(receipts, genesisHash(vec.contractId, "some-other-desk"));
    expect(result.valid).toBe(false);
    expect(result.brokenAt).toBe(1);
  });

  it("notices a receipt removed from the middle", () => {
    const receipts = vec.receipts.map((r) => r.receipt);
    const spliced = [...receipts.slice(0, 2), ...receipts.slice(3)];
    const result = verifyChain(spliced, genesisHash(vec.contractId, vec.deskId));
    expect(result.valid).toBe(false);
  });
});
